import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { ShipGap } from '../types'
import {
  bodyFiles,
  cardCreation,
  endsWithQuestion,
  heredocs,
  inlineBodies,
  isImplementPrompt,
  languageOf,
  proseWords,
  publishesText,
  resolvePath,
  shipGaps,
  textFields,
  usesItsaplan,
} from './lib'
import type { RepoFacts } from './lib'

type $ = EngineInterface

const isImplementing = atom({ plugin: 'guardrails', key: 'isImplementing' } as const, false)
const isCardBatchAllowed = atom({ plugin: 'guardrails', key: 'isCardBatchAllowed' } as const, false)

const CARD_CREATE_ONE = 'Criar este card'
const CARD_CREATE_BATCH = 'Criar todos até minha próxima mensagem'
const CARD_DENY =
  'guardrails: o usuário não autorizou criar este card. Não tente criar de novo nem por outro caminho. Se o card ainda fizer sentido, descreva-o na resposta (título, escopo, pai, bloqueios) e espere ele pedir.'

const LANGUAGE_DENY =
  'guardrails: este texto parece estar em inglês. Comentários, reviews e descrições de PR e de card destes projetos são em português do Brasil. Reescreva em pt-BR (termos técnicos e identificadores podem ficar como estão) e publique de novo. Se o inglês for intencional, inclua o marcador en-ok no texto.'

async function run($: $, argv: string[]): Promise<{ ok: boolean; out: string; err: string }> {
  const ran = await $.process.run(argv, { timeoutMs: 20_000 }).catch((error: unknown) => ({
    exitCode: -1,
    stdout: '',
    stderr: String(error),
  }))

  return { ok: ran.exitCode === 0, out: ran.stdout.trim(), err: ran.stderr.trim() }
}

async function repoFacts($: $): Promise<RepoFacts | undefined> {
  const branch = await run($, ['git', 'rev-parse', '--abbrev-ref', 'HEAD'])
  if (!branch.ok) return undefined
  const status = await run($, ['git', 'status', '--porcelain'])
  const unpushed = await run($, ['git', 'rev-list', '--count', 'HEAD', '--not', '--remotes'])
  const upstream = await run($, ['git', 'rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{u}'])
  const pr = await run($, ['gh', 'pr', 'view', '--json', 'state', '--jq', '.state'])
  const prState: RepoFacts['pr'] = pr.ok
    ? pr.out === 'OPEN' ? 'open' : 'closed'
    : /no (open )?pull requests? found/i.test(pr.err) ? 'none' : 'unknown'

  return {
    branch: branch.out,
    dirty: status.out === '' ? 0 : status.out.split('\n').length,
    unpushed: Number(unpushed.out) || 0,
    hasUpstream: upstream.ok,
    pr: prState,
  }
}

function shipMessage(gaps: readonly ShipGap[]): string {
  return [
    `guardrails: o /implement ainda não está entregue: ${gaps.join('; ')}.`,
    'Tarefa finalizada significa commit assinado, push e PR aberto (com o card em In Review e a evidência).',
    'Se a tarefa está pronta, faça isso agora.',
    'Se você está parando de propósito (esperando decisão do usuário, bloqueio, trabalho incompleto), não faça nada além de dizer, em uma linha, por que parou.',
  ].join(' ')
}

const CARD_QUESTION = 'Criar o card '
const CARD_REFUSE = 'Não criar'

/**
 * Pergunta ao usuário no diálogo do próprio Claude Code, fora do alcance do modo de
 * permissões. Diálogo fechado conta como recusa; resposta automática por ausência
 * vira recusa no hook de AskUserQuestion abaixo.
 */
async function askCardConsent($: $, card: string): Promise<'one' | 'batch' | { refused: string }> {
  const answer = await $.ui
    // Why: "Não criar" primeiro, para qualquer escolha padrão cair na recusa.
    .ask(`${CARD_QUESTION}${card}?`, { header: 'Novo card', options: [CARD_REFUSE, CARD_CREATE_ONE, CARD_CREATE_BATCH] })
    .catch(() => CARD_REFUSE)
  if (answer === CARD_CREATE_ONE) return 'one'
  if (answer === CARD_CREATE_BATCH) return 'batch'

  return { refused: answer === CARD_REFUSE ? '' : answer }
}

/**
 * O que o comando publica: o texto escrito no próprio comando (corpos na linha e
 * heredocs) e, à parte, o conteúdo dos arquivos de corpo.
 */
async function publishedText($: $, command: string): Promise<{ inline: string; files: string }> {
  const home = (await $.env.get('HOME')) ?? ''
  const files = await Promise.all(
    bodyFiles(command).map(file =>
      $.fs
        .read(resolvePath(file, command, home))
        .then(text => (typeof text === 'string' ? text : ''))
        .catch(() => ''),
    ),
  )

  return { inline: [...inlineBodies(command), ...heredocs(command)].join('\n'), files: files.join('\n') }
}

/**
 * A heurística decide quando o português é claro. Na dúvida (corpo montado em
 * script, pouco texto), um modelo pequeno lê e diz a língua da prosa.
 *
 * Why: só o texto escrito no comando vai ao modelo; ele já está na conversa.
 * O conteúdo de um arquivo, que pode ser um segredo, fica na heurística local:
 * este hook roda antes das permissões e não há como esperar a decisão delas.
 */
async function isEnglish($: $, text: string, files = ''): Promise<boolean> {
  if (`${text}\n${files}`.includes('en-ok')) return false
  const fileGuess = languageOf(files)
  if (fileGuess === 'en') return true
  const guess = languageOf(text)
  if (guess === 'pt' || fileGuess === 'pt' || proseWords(text) < 8) return false
  const answer = await $.model.complete({
    model: 'haiku',
    effort: 'low',
    maxTokens: 5,
    timeoutMs: 15_000,
    system: 'You classify the natural language of text that will be published as a code-review or issue comment. Ignore code, identifiers, file paths, shell syntax and JSON keys; judge only the human-readable prose. Answer with exactly one word: PT, EN or NONE.',
    prompt: text.slice(0, 6000),
  })
  if (!answer.isAnswered) return guess === 'en'

  return /^\s*EN\b/i.test(answer.text)
}

export const register: Register = (on, options) => {
  const projects = String(options.itsaplanProjects ?? '')
  const isLanguageOn = options.language !== false
  const isShipCheckOn = options.shipCheck !== false

  on('prompt.submit', async ($, e, next) => {
    if (isImplementPrompt(e.text)) await update($, isImplementing, () => true)
    await update($, isCardBatchAllowed, () => false)

    return next(e)
  })

  on('command.run', { command: /(^|:)implement$/ }, async ($, e, next) => {
    await update($, isImplementing, () => true)

    return next(e)
  })

  // Entrega: commit, push e PR antes de encerrar uma sessão de /implement.
  on('classic.Stop', async ($, e, next) => {
    const result = await next(e)
    if (!isShipCheckOn || e.stop_hook_active || e.agent_id !== undefined || result.block !== undefined) return result
    if (!(await read($, isImplementing))) return result
    if ((e.background_tasks?.length ?? 0) > 0 || (e.session_crons?.length ?? 0) > 0) return result
    if (endsWithQuestion(e.last_assistant_message)) return result
    const facts = await repoFacts($)
    const gaps = facts === undefined ? [] : shipGaps(facts)
    if (gaps.length === 0) return result
    $.ui.toast(`guardrails: falta ${gaps.join(', ')}`)

    return { ...result, block: shipMessage(gaps) }
  })

  // Card só com o consentimento do usuário, card a card ou por uma leva até a próxima mensagem dele.
  on('tool.call', { tool: /^(Bash|mcp__itsaplan__create_issue|mcp__linear__(create_issue|save_issue))$/ }, async ($, e, next) => {
    const card = cardCreation(e.tool, e.tool === 'Bash' ? e : (e as { input?: unknown }).input)
    if (card === undefined || (await read($, isCardBatchAllowed))) return next(e)
    // Why: nesses projetos o hook do Linear recusa a chamada; perguntar antes seria ruído.
    if (e.tool.startsWith('mcp__linear__') && usesItsaplan(await $.session.cwd(), projects)) return next(e)
    const consent = await askCardConsent($, card)
    if (consent === 'batch') await update($, isCardBatchAllowed, () => true)
    if (consent === 'one' || consent === 'batch') return next(e)

    return { deny: consent.refused === '' ? CARD_DENY : `${CARD_DENY} Resposta dele: "${consent.refused}".` }
  })

  // Só um clique do usuário autoriza: o diálogo que se resolveu sozinho por ausência vale como recusa.
  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    const result = await next(e)
    const answered = (result as { result?: { answers?: Record<string, string>; afkTimeoutMs?: number } }).result
    if (answered?.afkTimeoutMs === undefined || answered.answers === undefined) return result
    const answers = Object.fromEntries(
      Object.entries(answered.answers).map(([question, answer]) => [question, question.startsWith(CARD_QUESTION) ? CARD_REFUSE : answer]),
    )

    return { ...result, result: { ...answered, answers } } as typeof result
  })

  // pt-BR em tudo que o gh publica.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (!isLanguageOn || !publishesText(e.command)) return next(e)
    const { inline, files } = await publishedText($, e.command)
    if (!(await isEnglish($, inline, files))) return next(e)

    return { deny: LANGUAGE_DENY }
  })

  // E no que vai para os cards do It's a Plan.
  on('tool.call', { tool: /^mcp__itsaplan__(add_comment|update_comment|create_issue|update_issue|create_document|update_document)$/ }, async ($, e, next) => {
    if (!isLanguageOn || !(await isEnglish($, textFields(e)))) return next(e)

    return { deny: LANGUAGE_DENY }
  })

  // Projetos cujos cards estão no It's a Plan não usam o Linear.
  on('tool.call', { tool: /^mcp__linear__/ }, async ($, e, next) => {
    if (!usesItsaplan(await $.session.cwd(), projects)) return next(e)

    return {
      deny: "guardrails: os cards deste projeto estão no It's a Plan, não no Linear (mesmo que algum documento antigo do repo diga Linear). Use o MCP itsaplan: get_issue_by_number com a key e o número do card (ex.: ABC-90).",
    }
  })

  on('tool.call', { tool: 'Skill' }, async ($, e, next) => {
    if (!/linear/i.test(e.skill) || !usesItsaplan(await $.session.cwd(), projects)) return next(e)

    return {
      deny: `guardrails: a skill ${e.skill} é do Linear, e os cards deste projeto estão no It's a Plan. Use a skill dusky-itsaplan ou o MCP itsaplan.`,
    }
  })
}

