// Lógica pura do guardrails, separada para os testes.

/** O prompt que abre uma sessão de execução: /implement, com ou sem namespace. */
export function isImplementPrompt(text: string): boolean {
  return /^\s*\/(?:[\w-]+:)?implement\b/.test(text) || /<command-name>\/(?:[\w-]+:)?implement<\/command-name>/.test(text)
}

/** Termina pedindo algo ao usuário: aí parar é o certo e o Stop não cobra entrega. */
export function endsWithQuestion(message: string | undefined): boolean {
  const tail = (message ?? '').trim().split('\n').filter(line => line.trim() !== '').pop() ?? ''

  return /\?\s*[*_`)]*$/.test(tail)
}

const PT = new Set([
  'de', 'que', 'não', 'nao', 'os', 'das', 'dos', 'da', 'em', 'na', 'um', 'uma', 'para', 'com', 'por',
  'mais', 'mas', 'como', 'está', 'são', 'foi', 'isso', 'este', 'esta', 'também', 'ao', 'à', 'pelo', 'pela',
  'ou', 'já', 'quando', 'sem', 'sobre', 'entre', 'depois', 'ainda', 'aqui', 'porque', 'fica', 'agora',
  'nesta', 'neste', 'essa', 'esse', 'só', 'será', 'deve', 'pode', 'teste', 'código', 'linha', 'quem',
  'e', 'o', 'é', 'até', 'pelos', 'pelas', 'nos', 'nas', 'seu', 'sua', 'foram', 'corrigido', 'execução',
])

const EN = new Set([
  'the', 'and', 'is', 'are', 'of', 'this', 'that', 'it', 'with', 'for', 'be', 'was', 'not', 'should',
  'would', 'can', 'when', 'which', 'from', 'but', 'has', 'have', 'by', 'an', 'at', 'we', 'you', 'its',
  'does', 'here', 'there', 'these', 'those', 'will', 'also', 'only', 'than', 'then', 'because', 'into',
  'missing', 'instead', 'test', 'code', 'line', 'could', 'still', 'now', 'what', 'why',
])

/** Quantas palavras de prosa o texto tem, fora código e links. */
export function proseWords(text: string): number {
  return (stripCode(text).match(/[a-zà-ÿ]{3,}/gi) ?? []).length
}

function stripCode(text: string): string {
  return text
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/`[^`]*`/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
}

/** Conta palavras de função das duas línguas; identificadores e código pesam pouco. */
export function languageOf(text: string): 'pt' | 'en' | 'unknown' {
  const prose = stripCode(text)
  let pt = 0
  let en = 0
  for (const word of prose.toLowerCase().match(/[a-zà-ÿ]+/g) ?? []) {
    if (PT.has(word)) pt += 1
    if (EN.has(word)) en += 1
  }
  if (pt + en < 6) return 'unknown'
  if (en >= 5 && en > pt * 2) return 'en'

  return pt > 0 ? 'pt' : 'unknown'
}

const SEGMENT = /;|&&|\|\||\||\n|\$\(|`/

/** Trechos do comando em que o próprio gh é o comando (não um texto que cita gh). */
export function ghSegments(command: string): string[] {
  return command
    .split(SEGMENT)
    .map(part => part.trim().replace(/^(?:[A-Za-z_][A-Za-z0-9_]*=\S*\s+)*/, ''))
    .filter(part => /^gh\s/.test(part))
}

/** Comandos gh que publicam texto em PR ou issue (leituras como `gh api ... --jq` não contam). */
export function publishesText(command: string): boolean {
  return ghSegments(command).some(part => {
    if (/^gh\s+(pr|issue)\s+(comment|review|create|edit)\b/.test(part)) return true
    if (!/^gh\s+api\b/.test(part)) return false
    if (/\bgraphql\b/.test(part)) {
      return /mutation/.test(command) && /(add\w*Review\w*|addComment|\w*Reply|updatePullRequest|updateIssueComment)/.test(command)
    }
    const isWrite = /(-X|--method)\s+(POST|PATCH|PUT)\b/i.test(part) || /(^|\s)(-f|-F|--field|--raw-field|--input)\s/.test(part)

    return isWrite && /(comments|reviews|replies|\/pulls\/\d+\s|\/issues\/\d+\s)/.test(`${part} `)
  })
}

/** Corpos passados na linha: --body, -b, --title, -f body=, -F body=. */
export function inlineBodies(command: string): string[] {
  const bodies: string[] = []
  const flag = /(?:--body|--title|(?<=\s)-[bt]|(?:-f|-F|--field|--raw-field)\s+(?:body|title))[=\s]\s*(?:"((?:[^"\\]|\\.)*)"|'([^']*)')/g
  for (const match of command.matchAll(flag)) {
    const body = match[1] ?? match[2]
    if (body !== undefined) bodies.push(body)
  }

  return bodies
}

/** Corpos de heredoc (<<EOF ... EOF), onde o texto publicado costuma estar. */
export function heredocs(command: string): string[] {
  const bodies: string[] = []
  for (const match of command.matchAll(/<<-?\s*(['"]?)(\w+)\1[^\n]*\n([\s\S]*?)\n\s*\2\s*(?:\n|$)/g)) {
    if (match[3] !== undefined) bodies.push(match[3])
  }

  return bodies
}

/** Troca $VAR, ${VAR} e ~ pelas atribuições do próprio comando e pelo HOME. */
export function resolvePath(path: string, command: string, home: string): string {
  const vars: Record<string, string> = { HOME: home }
  for (const match of command.matchAll(/(?:^|[\s;&(])([A-Za-z_][A-Za-z0-9_]*)=(?:"([^"]*)"|'([^']*)'|([^\s;&|]*))/g)) {
    const [, name, double, single, bare] = match
    if (name !== undefined) vars[name] = double ?? single ?? bare ?? ''
  }
  const expanded = path.replace(/\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?/g, (whole, name: string) => vars[name] ?? whole)

  return expanded.startsWith('~/') ? `${home}${expanded.slice(1)}` : expanded
}

/** Arquivos de onde o gh lê o corpo: --body-file, -F f, -F body=@f, --input f. */
export function bodyFiles(command: string): string[] {
  const files: string[] = []
  const patterns = [
    /--body-file[=\s]+(['"]?)([^\s'"]+)\1/g,
    /(?:^|\s)-F\s+(['"]?)(?![\w.]+=)([^\s'"]+)\1/g,
    /(?:-F|--field|-f|--raw-field)\s+(['"]?)[\w.]+=@([^\s'"]+)\1/g,
    /--input[=\s]+(['"]?)([^\s'"]+)\1/g,
    /(?:--body-file|--input|-F|=@)\s*-(?:\s.*?)?\s<\s*(['"]?)([^\s'"]+)\1/g,
  ]
  for (const segment of ghSegments(command)) {
    for (const pattern of patterns) {
      for (const match of segment.matchAll(pattern)) {
        const file = match[2]
        if (file !== undefined && file !== '-') files.push(file)
      }
    }
  }

  return files
}

/** Todo texto de um input de ferramenta MCP, menos ids e chaves. */
export function textFields(input: unknown): string {
  if (typeof input === 'string') return input
  if (Array.isArray(input)) return input.map(textFields).join('\n')
  if (input !== null && typeof input === 'object') {
    return Object.entries(input)
      .filter(([key]) => !/id$|^key$|^tool/i.test(key))
      .map(([, value]) => textFields(value))
      .join('\n')
  }

  return ''
}

/** O repositório do cwd está na lista dos que usam o It's a Plan. */
export function usesItsaplan(cwd: string, projects: string): boolean {
  const names = projects.split(',').map(name => name.trim().toLowerCase()).filter(Boolean)
  const segments = cwd.toLowerCase().split('/')

  return names.some(name => segments.some(segment => segment === name || segment.startsWith(`${name}-`)))
}

export type RepoFacts = {
  branch: string
  dirty: number
  unpushed: number
  hasUpstream: boolean
  pr: 'open' | 'closed' | 'none' | 'unknown'
}

const BASE_BRANCHES = new Set(['main', 'master', 'develop', 'HEAD'])

/** O que falta para a entrega estar completa: commit, push e PR. */
export function shipGaps(facts: RepoFacts): string[] {
  if (BASE_BRANCHES.has(facts.branch)) return []
  const gaps: string[] = []
  if (facts.dirty > 0) gaps.push(`${facts.dirty} arquivo(s) alterado(s) sem commit`)
  if (facts.unpushed > 0) gaps.push(`${facts.unpushed} commit(s) do branch ${facts.branch} sem push`)
  const hasWork = facts.dirty > 0 || facts.unpushed > 0 || facts.hasUpstream
  if (hasWork && facts.pr === 'none') gaps.push(`nenhum PR aberto para o branch ${facts.branch}`)

  return gaps
}

const CREATES_CARD = /^mcp__(itsaplan__create_issue|linear__(create_issue|save_issue))$/

function stringField(input: unknown, key: string): string | undefined {
  if (input === null || typeof input !== 'object') return undefined
  const value = (input as Record<string, unknown>)[key]

  return typeof value === 'string' && value !== '' ? value : undefined
}

/** O card que a chamada criaria, descrito para a pergunta; undefined quando ela não cria card. */
export function cardCreation(tool: string, input: unknown): string | undefined {
  if (tool === 'Bash') {
    const segment = ghSegments(stringField(input, 'command') ?? '').find(part => /^gh\s+issue\s+create\b/.test(part))
    if (segment === undefined) return undefined
    const title = /--title[=\s]+(?:"((?:[^"\\]|\\.)*)"|'([^']*)')/.exec(segment)

    return `"${title?.[1] ?? title?.[2] ?? 'sem título'}" no GitHub`
  }
  if (!CREATES_CARD.test(tool)) return undefined
  // Why: save_issue do Linear com id é edição, não criação.
  if (tool.endsWith('save_issue') && stringField(input, 'id') !== undefined) return undefined
  const where = stringField(input, 'projectKey') ?? stringField(input, 'team') ?? stringField(input, 'teamId') ?? 'o tracker'

  return `"${stringField(input, 'title') ?? 'sem título'}" em ${where}`
}

