/** Uma pendência de entrega: o que falta antes de encerrar o /implement. */
export type ShipGap = string

declare module 'claude-code' {
  interface PluginState {
    guardrails: {
      /** A sessão começou por /implement: entregar é commit, push e PR. */
      isImplementing: boolean
      /** O usuário autorizou criar cards até a próxima mensagem dele. */
      isCardBatchAllowed: boolean
    }
  }
}
